Window::~Window(){persistHistory();if(process){process->kill();process->waitForFinished(1000);}}
void Window::toast(const QString& message){status->setText(message);QTimer::singleShot(5000,this,[this,message]{if(status->text()==message)status->setText(QStringLiteral("就绪"));});}
void Window::toggleVisible(){showNormal();raise();activateWindow();}
void Window::closeEvent(QCloseEvent* e){if(quitting){e->accept();return;}if(QSystemTrayIcon::isSystemTrayAvailable()){hide();e->ignore();}else{quitting=true;e->accept();qApp->quit();}}
void Window::refreshHistory(){QSignalBlocker blocked(history);history->clear();for(const auto& c:captures){auto item=new QListWidgetItem;item->setSizeHint(QSize(140,143));item->setToolTip(c->name);history->addItem(item);auto card=new QWidget;card->setAttribute(Qt::WA_TransparentForMouseEvents);auto layout=new QVBoxLayout(card);layout->setContentsMargins(8,8,8,8);layout->setSpacing(6);auto thumb=new QLabel;thumb->setAlignment(Qt::AlignCenter);thumb->setFixedHeight(82);thumb->setPixmap(QPixmap::fromImage(c->image.scaled(132,82,Qt::KeepAspectRatio,Qt::SmoothTransformation)));layout->addWidget(thumb);auto label=new QLabel(QFontMetrics(font()).elidedText(c->name,Qt::ElideRight,135));label->setStyleSheet("font-size:10px;");layout->addWidget(label);auto meta=new QLabel(c->sample?QStringLiteral("示例文档"):QString("%1 × %2 px").arg(c->image.width()).arg(c->image.height()));meta->setObjectName("muted");layout->addWidget(meta);history->setItemWidget(item,card);}}
void Window::addCapture(Capture c){if(c.image.isNull())return;c.image.setDevicePixelRatio(1);captures.insert(captures.begin(),std::make_unique<Capture>(std::move(c)));refreshHistory();history->setCurrentRow(0);saveHistory();}
void Window::select(int row){if(row<0||row>=int(captures.size())){current=nullptr;canvas->setCapture(nullptr);return;}current=captures[row].get();title->setText(current->name+(current->sample?QStringLiteral("   · 示例"):QString()));dimensions->setText(QString("%1 × %2 px").arg(current->image.width()).arg(current->image.height()));canvas->setCapture(current);refreshResult();}
void Window::refreshResult(){updating=true;text->setPlainText(current?current->text:QString());table->clear();table->setRowCount(current?current->table.size():0);int cols=0;if(current)for(const auto& r:current->table)cols=qMax(cols,int(r.size()));table->setColumnCount(cols);if(current)for(int r=0;r<current->table.size();r++)for(int c=0;c<cols;c++)table->setItem(r,c,new QTableWidgetItem(current->table[r].value(c)));engine->setText(current&&!current->engine.isEmpty()?current->engine:QStringLiteral("系统 OCR"));exportButton->setEnabled(current);text->setEnabled(current);table->setEnabled(current);recognizeButton->setEnabled(current&&!ocrBusy);tableReference->setVisible(current&&!current->table.isEmpty());if(current)tableReference->setText(QStringLiteral("另有 %1 行表格，点击查看 →").arg(current->table.size()));updating=false;}
void Window::syncTable(){if(!current)return;current->table.clear();for(int r=0;r<table->rowCount();r++){QStringList row;for(int c=0;c<table->columnCount();c++)row<< (table->item(r,c)?table->item(r,c)->text():QString());current->table<<row;}saveHistory();}
void Window::importImage(){auto path=QFileDialog::getOpenFileName(this,QStringLiteral("导入图片"),{},QStringLiteral("图像 (*.png *.jpg *.jpeg *.webp *.bmp)"));if(!path.isEmpty())openImage(path);}
void Window::openImage(const QString& path){if(QFileInfo(path).size()>25*1024*1024){QMessageBox::warning(this,QStringLiteral("无法导入"),QStringLiteral("图片超过 25 MB，请缩小后导入。"));return;}QImageReader reader(path);auto size=reader.size();if(!size.isValid()||qint64(size.width())*size.height()>50000000){QMessageBox::warning(this,QStringLiteral("无法导入"),QStringLiteral("图片无效或超过 5000 万像素。"));return;}reader.setAutoTransform(true);auto image=reader.read();if(image.isNull()){QMessageBox::warning(this,QStringLiteral("无法导入"),reader.errorString());return;}Capture c;c.name=QFileInfo(path).completeBaseName();c.image=image;addCapture(std::move(c));}
void Window::dragEnterEvent(QDragEnterEvent* e){if(e->mimeData()->hasUrls()||e->mimeData()->hasImage())e->acceptProposedAction();}
void Window::dropEvent(QDropEvent*e){if(e->mimeData()->hasUrls()){auto urls=e->mimeData()->urls();if(!urls.isEmpty()&&urls.first().isLocalFile())openImage(urls.first().toLocalFile());}else if(e->mimeData()->hasImage()){Capture c;c.name=QStringLiteral("拖入图片");c.image=qvariant_cast<QImage>(e->mimeData()->imageData());addCapture(std::move(c));}e->acceptProposedAction();}
void Window::startCapture(){if(capturing)return;
#ifdef Q_OS_MAC
 if(!CGPreflightScreenCaptureAccess()){CGRequestScreenCaptureAccess();QMessageBox::information(this,QStringLiteral("需要屏幕录制权限"),QStringLiteral("请在系统设置 → 隐私与安全性 → 屏幕与系统音频录制中允许萌知，然后重启应用。您仍可导入图片进行识别。"));return;}
#endif
 capturing=true;bool wasVisible=isVisible();hide();QTimer::singleShot(180,this,[this,wasVisible]{auto screen=QGuiApplication::screenAt(QCursor::pos());if(!screen)screen=QGuiApplication::primaryScreen();auto shot=screen->grabWindow(0).toImage();if(shot.isNull()){capturing=false;if(wasVisible)toggleVisible();QMessageBox::warning(this,QStringLiteral("截图失败"),QStringLiteral("未能捕获屏幕，请检查系统权限。"));return;}auto overlay=new Overlay(screen,shot);connect(overlay,&Overlay::canceled,this,[this,wasVisible]{capturing=false;if(wasVisible)toggleVisible();});connect(overlay,&Overlay::selected,this,[this](QImage image,int action){capturing=false;if(action==0){QApplication::clipboard()->setImage(image);return;}if(action==3){pin(image);return;}if(action==4){auto name=QFileDialog::getSaveFileName(nullptr,QStringLiteral("保存截图"),QStringLiteral("截图.png"),"PNG (*.png)");if(!name.isEmpty()&&!image.save(name,"PNG"))QMessageBox::warning(nullptr,QStringLiteral("保存失败"),QStringLiteral("请检查保存位置是否可写。"));return;}Capture c;c.name=QStringLiteral("截图 ")+QDateTime::currentDateTime().toString("MM-dd HH:mm:ss");c.image=image;addCapture(std::move(c));toggleVisible();if(action==2)recognize();});});}
void Window::pin(const QImage& image){if(image.isNull())return;if(pins>=12){toast(QStringLiteral("最多同时打开 12 张贴图"));return;}auto w=new PinWindow(image);pinWindows.push_back(w);connect(w,&PinWindow::editRequested,this,[this,w](QImage image){Capture c;c.name=QStringLiteral("贴图标注");c.image=image;addCapture(std::move(c));toggleVisible();});pins++;connect(w,&QObject::destroyed,this,[this]{pins--;});}
void Window::copyText(){if(!current)return;QString out;if(tabs->currentIndex()==0)out=text->toPlainText();else{QStringList rows;for(const auto& row:current->table)rows<<row.join('\t');out=rows.join('\n');}if(out.isEmpty()){toast(QStringLiteral("没有可复制的内容"));return;}QApplication::clipboard()->setText(out);toast(QStringLiteral("已复制到剪贴板"));}
void Window::recognize(){
 if(!current||ocrBusy)return;if(current->sample){toast(QStringLiteral("这是内置示例；请导入自己的图片体验真实识别"));return;}
 if(current->ocrComplete){refreshResult();toast(QStringLiteral("已复用本图识别结果，无需等待"));return;}
 auto target=current;const QImage image=target->image;ocrBusy=true;recognizeButton->setEnabled(false);removeButton->setEnabled(false);canvas->setScanning(true);recognizeButton->setText(QStringLiteral("正在识别…"));toast(QStringLiteral("正在后台识别，您可以继续查看图片"));
 auto watcher=new QFutureWatcher<Ocr::Result>(this);QElapsedTimer elapsed;elapsed.start();
 connect(watcher,&QFutureWatcher<Ocr::Result>::finished,this,[this,watcher,target,elapsed]{
  const auto result=watcher->result();watcher->deleteLater();ocrBusy=false;canvas->setScanning(false);recognizeButton->setText(QStringLiteral("识别文字     本机 OCR"));removeButton->setEnabled(true);
  if(!result.error.isEmpty()){recognizeButton->setEnabled(current);QMessageBox::warning(this,QStringLiteral("识别失败"),result.error);return;}
  auto object=result.data;target->text=object.value("text").toString();target->engine=object.value("engine").toString();target->blocks.clear();
  for(const auto& value:object.value("blocks").toArray()){auto b=value.toObject();target->blocks.push_back({b["text"].toString(),QRectF(b["x"].toDouble(),b["y"].toDouble(),b["width"].toDouble(),b["height"].toDouble()),b["confidence"].toDouble(-1)});}
  target->table=Export::inferTable(target->blocks);target->ocrComplete=true;if(current==target)refreshResult();else recognizeButton->setEnabled(current);saveHistory();
  toast(target->text.isEmpty()?QStringLiteral("没有找到文字，请尝试更清晰的图片"):QStringLiteral("识别完成 · %1 秒，可直接校对文字与表格").arg(elapsed.elapsed()/1000.0,0,'f',2));
 });
 watcher->setFuture(QtConcurrent::run(Ocr::pool(),[image]{return Ocr::recognize(image);}));
}
